// Turns the reference tables in reference-data/ into src/lib/growth-data.ts.
// Run: npm run build:growth   (only needed when a CSV in reference-data/ changes)
//
// Nothing is rounded, smoothed or thinned here: every number is written exactly as it
// stands in the CSV. src/lib/growth-reference.test.ts re-reads the CSVs and fails if the
// generated file and the tables ever disagree.
import { readFileSync, writeFileSync } from 'node:fs'

const read = (name) => {
  const [head, ...lines] = readFileSync(new URL(`../reference-data/${name}`, import.meta.url), 'utf8').trim().split('\n')
  const cols = head.split(',')
  return lines.map((line) => Object.fromEntries(line.split(',').map((cell, i) => [cols[i], cell])))
}
const list = (cells) => `[${cells.join(',')}]`

const who = (file) => {
  const rows = read(file)
  rows.forEach((r, i) => {
    if (Number(r.Day) !== i) throw new Error(`${file}: row ${i} is day ${r.Day}`)
    if (Number(r.L) !== 1) throw new Error(`${file}: L is ${r.L} on day ${r.Day}`)
  })
  return `{ M: ${list(rows.map((r) => r.M))}, S: ${list(rows.map((r) => r.S))} }`
}

const iapRows = read('iap2015-lms.csv')
iapRows.forEach((r, i) => {
  if (Number(r.age_months) !== 60 + i) throw new Error(`iap2015-lms.csv: row ${i} is month ${r.age_months}`)
})
const iap = (measure, sex) => `{ ${['L', 'M', 'S'].map((p) => `${p}: ${list(iapRows.map((r) => r[`${measure}_${sex}_${p}`]))}`).join(', ')} }`

const out = `/* AUTO-GENERATED by scripts/build-growth-data.mjs from reference-data/*.csv. DO NOT EDIT BY HAND.
 *
 * Reference tables only; no patient data. Sources and checks: reference-data/README.md.
 *
 * WHO_LHFA  WHO Child Growth Standards 2006, length/height-for-age. One entry per day of age,
 *           day 0 to day 1856. Recumbent length to day 730, standing height from day 731.
 *           L is 1 on every day, so only M and S are stored.
 * IAP_LMS   IAP 2015 growth charts, 5 to 18 years. One entry per month of age, 60 to 216 months.
 */
/* oxlint-disable */

export const WHO_LHFA: Record<'M' | 'F', { M: number[]; S: number[] }> = {
  M: ${who('who2006-lhfa-boys.csv')},
  F: ${who('who2006-lhfa-girls.csv')},
}

export const IAP_LMS: Record<'height' | 'weight' | 'bmi', Record<'M' | 'F', { L: number[]; M: number[]; S: number[] }>> = {
${['height', 'weight', 'bmi'].map((m) => `  ${m}: {\n    M: ${iap(m, 'boys')},\n    F: ${iap(m, 'girls')},\n  },`).join('\n')}
}
`
writeFileSync(new URL('../src/lib/growth-data.ts', import.meta.url), out)
console.log(`src/lib/growth-data.ts written (${(out.length / 1024).toFixed(0)} KB)`)
